using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

builder.Services.AddSingleton<TicketModelTrainer>();

// Train the model at startup so the pool can load it
var tempProvider = builder.Services.BuildServiceProvider();
var trainer = tempProvider.GetRequiredService<TicketModelTrainer>();
trainer.Train();

builder.Services.AddSingleton(trainer);
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

